#!/usr/bin/env python3
"""Debug template processing."""

from collections import defaultdict
from wikidict.lang.en.template_handlers import render_foreign_derivation

# Test inh template directly
print("Testing inh template:")
result = render_foreign_derivation("inh", ["en", "ang", "þē", "", "the, that"], defaultdict(str, {
    "pos": "demonstrative pronoun",
    "g": "m"
}))
print(f"Result: {result}")

# Test m template directly  
print("\nTesting m template:")
result = render_foreign_derivation("m", ["ang", "sē"], defaultdict(str, {
    "g": "m"
}))
print(f"Result: {result}")

# Test m template with f
print("\nTesting m template with feminine:")
result = render_foreign_derivation("m", ["ang", "sēo"], defaultdict(str, {
    "g": "f"
}))
print(f"Result: {result}")
